<?php
declare(strict_types=1);
require_once __DIR__.'/auth_check.php';\AccessManager::requirePageAccess();require_once __DIR__.'/model/Database.php';require_once __DIR__.'/services/FebHumanDocumentReviewService.php';
$uid=(int)($_SESSION['user_id']??0);$service=null;$rows=[];$error='';
try{
    $service=new FebHumanDocumentReviewService(Database::getConnection());
    $reviewers=$service->reviewers();
    if(!in_array($uid,array_map('intval',array_column($reviewers,'id')),true)){http_response_code(403);exit('Accès réservé aux validateurs configurés.');}
    $_SESSION['feb_human_review_csrf']??=bin2hex(random_bytes(32));
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
        if(!hash_equals((string)$_SESSION['feb_human_review_csrf'],(string)($_POST['_csrf']??'')))throw new RuntimeException('Session expirée.');
        $decision=(string)($_POST['decision']??'');
        if(!$service->decide((int)($_POST['review_id']??0),$uid,$decision,(string)($_POST['reason']??''),trim((string)(($_SESSION['prenom']??'').' '.($_SESSION['nom']??'')))?:'Validateur'))throw new RuntimeException('Cette demande a déjà été traitée.');
        header('Location: validation_justificatifs_feb.php');exit;
    }
    $rows=$service->pendingFor($uid);
}catch(Throwable $e){
    error_log('[feb_human_review_page] '.$e->getMessage());
    $error=$e->getMessage();
    if($service instanceof FebHumanDocumentReviewService){
        try{$rows=$service->pendingFor($uid);}catch(Throwable){}
    }
}
